export function getToolBySlug(slug: string): ToolItem | undefined {
  return TOOLS.find((t) => t.slug === slug);
}

export function getToolsByCategory(categoryId: string): ToolItem[] {
  return TOOLS.filter((t) => t.category === categoryId);
}

export function getPopularTools(): ToolItem[] {
  return TOOLS.filter((t) => t.popular);
}

export function getRelatedTools(currentTool: ToolItem, limit = 4): ToolItem[] {
  return TOOLS
    .filter((t) => t.category === currentTool.category && t.id !== currentTool.id)
    .slice(0, limit);
}
